#include <iostream>
#include <stdexcept>

struct File {
    File()  { std::cout << "open\n"; }
    ~File() { std::cout << "close\n"; }   // 无论正常/异常退出都会调用
};

int main() {
    try {
        File f;                  // RAII 资源
        std::cout << "work\n";
        throw std::runtime_error("fail");
    } catch (const std::exception& e) {
        std::cout << "handled: " << e.what() << '\n';
    }
}
